import {
  Controller,
  Get,
  Query,
  UseGuards,
  Request,
  ParseIntPipe,
  DefaultValuePipe,
  Res,
} from '@nestjs/common';
import type { Response } from 'express';
import {
  ApiTags,
  ApiCookieAuth,
  ApiOperation,
  ApiProduces,
} from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { ActivityLogsService } from './activity-logs.service';

@ApiTags('activity-logs')
@ApiCookieAuth()
@UseGuards(JwtAuthGuard)
@Controller('activity-logs')
export class ActivityLogsController {
  constructor(private activityLogsService: ActivityLogsService) {}

  @Get()
  @ApiOperation({ summary: 'Get activity logs' })
  findAll(
    @Request() req: any,
    @Query('page', new DefaultValuePipe(1), ParseIntPipe) page?: number,
    @Query('limit', new DefaultValuePipe(20), ParseIntPipe) limit?: number,
    @Query('search') search?: string,
    @Query('action') action?: string,
    @Query('startDate') startDate?: string,
    @Query('endDate') endDate?: string,
    @Query('status') status?: string,
  ) {
    return this.activityLogsService.findAll(
      req.user.id,
      page,
      limit,
      search,
      action,
      startDate,
      endDate,
      status,
    );
  }

  @Get('export')
  @ApiOperation({ summary: 'Export activity logs to CSV' })
  @ApiProduces('text/csv')
  async export(
    @Request() req: any,
    @Res() res: Response,
    @Query('search') search?: string,
    @Query('action') action?: string,
    @Query('startDate') startDate?: string,
    @Query('endDate') endDate?: string,
    @Query('status') status?: string,
  ) {
    const csv = await this.activityLogsService.exportLogs(
      req.user.id,
      search,
      action,
      startDate,
      endDate,
      status,
    );
    res.header('Content-Type', 'text/csv');
    res.attachment('activity-logs.csv');
    return res.send(csv);
  }

  @Get('recent')
  @ApiOperation({ summary: 'Get recent activity logs' })
  findRecent(@Request() req: any) {
    return this.activityLogsService.findRecent(req.user.id, 10);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PrismaService } from '../prisma/prisma.service';

interface CreateLogDto {
  userId: string;
  projectId?: string;
  action: string;
  description?: string;
  ipAddress?: string;
}

@Injectable()
export class ActivityLogsService {
  private readonly logger = new Logger(ActivityLogsService.name);

  constructor(private prisma: PrismaService) {}

  // Runs automatically every day at midnight (00:00)
  @Cron(CronExpression.EVERY_DAY_AT_MIDNIGHT)
  async deleteOldLogs() {
    this.logger.log('Starting scheduled cleanup for old activity logs...');
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    try {
      const { count } = await this.prisma.activityLog.deleteMany({
        where: {
          createdAt: {
            lt: thirtyDaysAgo,
          },
        },
      });
      if (count > 0) {
        this.logger.log(
          `Successfully deleted ${count} old activity log(s) older than 30 days.`,
        );
      } else {
        this.logger.log('No old activity logs found to delete.');
      }
    } catch (error) {
      this.logger.error(
        'Failed to execute daily cleanup for activity logs',
        error,
      );
    }
  }

  async create(dto: CreateLogDto) {
    return this.prisma.activityLog.create({
      data: {
        userId: dto.userId,
        projectId: dto.projectId,
        action: dto.action,
        description: dto.description,
        ipAddress: dto.ipAddress,
      },
    });
  }

  async findAll(
    userId: string,
    page = 1,
    limit = 20,
    search?: string,
    actionFilter?: string,
    startDate?: string,
    endDate?: string,
    status?: string,
  ) {
    const whereClause: any = { userId };

    if (search) {
      whereClause.OR = [
        { action: { contains: search, mode: 'insensitive' } },
        { description: { contains: search, mode: 'insensitive' } },
        { project: { name: { contains: search, mode: 'insensitive' } } },
      ];
    }

    if (actionFilter && actionFilter !== 'All Actions') {
      whereClause.action = { contains: actionFilter, mode: 'insensitive' };
    }

    if (status && status !== 'All Status') {
      whereClause.status = status;
    }

    if (startDate || endDate) {
      whereClause.createdAt = {};
      if (startDate) whereClause.createdAt.gte = new Date(startDate);
      if (endDate) {
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        whereClause.createdAt.lte = end;
      }
    }

    const [total, logs] = await Promise.all([
      this.prisma.activityLog.count({ where: whereClause }),
      this.prisma.activityLog.findMany({
        where: whereClause,
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
        include: {
          project: { select: { id: true, name: true } },
          user: { select: { name: true, email: true } },
        },
      }),
    ]);

    return {
      data: logs,
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    };
  }

  async findRecent(userId: string, limit = 5) {
    return this.prisma.activityLog.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      take: limit,
      include: {
        project: { select: { id: true, name: true } },
        user: { select: { name: true, email: true } },
      },
    });
  }

  async exportLogs(
    userId: string,
    search?: string,
    actionFilter?: string,
    startDate?: string,
    endDate?: string,
    status?: string,
  ): Promise<string> {
    const whereClause: any = { userId };

    if (search) {
      whereClause.OR = [
        { action: { contains: search, mode: 'insensitive' } },
        { description: { contains: search, mode: 'insensitive' } },
        { project: { name: { contains: search, mode: 'insensitive' } } },
      ];
    }

    if (actionFilter && actionFilter !== 'All Actions') {
      whereClause.action = { contains: actionFilter, mode: 'insensitive' };
    }

    if (status && status !== 'All Status') {
      whereClause.status = status;
    }

    if (startDate || endDate) {
      whereClause.createdAt = {};
      if (startDate) whereClause.createdAt.gte = new Date(startDate);
      if (endDate) {
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        whereClause.createdAt.lte = end;
      }
    }

    const logs = await this.prisma.activityLog.findMany({
      where: whereClause,
      orderBy: { createdAt: 'desc' },
      include: {
        project: { select: { name: true } },
        user: { select: { name: true } },
      },
    });

    const header = [
      'Time',
      'User',
      'Action',
      'Target',
      'Description',
      'Status',
    ];
    const rows = logs.map((log) => [
      log.createdAt.toISOString(),
      log.user?.name || 'User',
      log.action,
      log.project?.name || 'System',
      `"${(log.description || '').replace(/"/g, '""')}"`,
      log.status || 'Success',
      log.ipAddress || '-',
    ]);

    return [header.join(','), ...rows.map((r) => r.join(','))].join('\n');
  }
}

import { Injectable, Logger } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import extractZip from 'extract-zip';

@Injectable()
export class ArchiveService {
  private readonly logger = new Logger(ArchiveService.name);

  async extractAndFlatten(filePath: string, extractDir: string): Promise<void> {
    this.logger.log(`Extracting ZIP from ${filePath} to ${extractDir}`);
    await extractZip(filePath, { dir: extractDir });
    this.flattenDirectory(extractDir);
  }

  private flattenDirectory(dir: string) {
    const items = fs.readdirSync(dir);
    if (items.length === 1) {
      const singleItemPath = path.join(dir, items[0]);
      if (fs.statSync(singleItemPath).isDirectory()) {
        this.logger.log(`Flattening root folder: ${items[0]}`);
        const innerItems = fs.readdirSync(singleItemPath);
        for (const item of innerItems) {
          fs.renameSync(path.join(singleItemPath, item), path.join(dir, item));
        }
        fs.rmSync(singleItemPath, { recursive: true, force: true });
      }
    }
  }

  cleanup(extractDir: string, filePath?: string) {
    try {
      if (extractDir && fs.existsSync(extractDir)) {
        // Hapus folder ekstrak (contoh: uploads/<projectId>/<timestamp>)
        fs.rmSync(extractDir, { recursive: true, force: true });

        // Cek parent folder (contoh: uploads/<projectId>)
        const parentDir = path.dirname(extractDir);
        if (fs.existsSync(parentDir)) {
          const items = fs.readdirSync(parentDir);
          // Jika parent folder sudah kosong (tidak ada folder timestamp lain), hapus parent-nya juga
          if (items.length === 0) {
            fs.rmSync(parentDir, { recursive: true, force: true });
            this.logger.log(`Cleaned up empty project folder: ${parentDir}`);
          }
        }
      }
      if (filePath && fs.existsSync(filePath)) {
        // Hapus file ZIP asli
        fs.unlinkSync(filePath);
      }
    } catch (err) {
      this.logger.warn(`Cleanup failed: ${err.message}`);
    }
  }
}

import {
  Controller,
  Post,
  Get,
  Body,
  UseGuards,
  Request,
  Ip,
  Delete,
  Res,
  Param,
} from '@nestjs/common';
import type { Response } from 'express';
import {
  ApiTags,
  ApiOperation,
  ApiCookieAuth,
  ApiParam,
  ApiResponse,
  ApiExcludeEndpoint,
} from '@nestjs/swagger';
import { AuthService } from './auth.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';
import { UpdateProfileDto } from './dto/update-profile.dto';
import { UpdatePasswordDto } from './dto/update-password.dto';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { RolesGuard } from './guards/roles.guard';
import { Roles } from './decorators/roles.decorator';
import { Role } from '@generated/prisma';

@ApiTags('auth')
@Controller('auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @Post('register')
  @ApiOperation({ summary: 'Register a new user' })
  async register(
    @Body() dto: RegisterDto,
    @Ip() ip: string,
    @Res({ passthrough: true }) res: Response,
  ) {
    const data = await this.authService.register(dto, ip);
    res.cookie('access_token', data.token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });
    return data;
  }

  @Post('login')
  @ApiOperation({ summary: 'Login and get JWT token' })
  async login(
    @Body() dto: LoginDto,
    @Ip() ip: string,
    @Res({ passthrough: true }) res: Response,
  ) {
    const data = await this.authService.login(dto, ip);
    res.cookie('access_token', data.token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    });
    return data;
  }

  @Post('logout')
  @ApiOperation({ summary: 'Logout and clear cookie' })
  logout(@Res({ passthrough: true }) res: Response) {
    res.clearCookie('access_token');
    return { message: 'Logged out successfully' };
  }

  @Get('me')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Get current user profile' })
  getMe(@Request() req: any) {
    return this.authService.getMe(req.user.id);
  }

  @Post('profile')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Update user profile' })
  updateProfile(
    @Request() req: any,
    @Body() dto: UpdateProfileDto,
    @Ip() ip: string,
  ) {
    return this.authService.updateProfile(req.user.id, dto, ip);
  }

  @Post('password')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Update user password' })
  updatePassword(
    @Request() req: any,
    @Body() dto: UpdatePasswordDto,
    @Ip() ip: string,
  ) {
    return this.authService.updatePassword(req.user.id, dto, ip);
  }

  @Post('ssh-key')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Generate a new SSH key pair' })
  generateSshKey(@Request() req: any, @Ip() ip: string) {
    return this.authService.generateSshKey(req.user.id, ip);
  }

  @Post('github')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Connect GitHub via Personal Access Token' })
  connectGithub(
    @Request() req: any,
    @Body('token') token: string,
    @Ip() ip: string,
  ) {
    return this.authService.connectGithub(req.user.id, token, ip);
  }

  @Delete('github')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Disconnect GitHub account' })
  disconnectGithub(@Request() req: any, @Ip() ip: string) {
    return this.authService.disconnectGithub(req.user.id, ip);
  }

  @Delete('me')
  @UseGuards(JwtAuthGuard)
  @ApiCookieAuth()
  @ApiOperation({ summary: 'Delete own account and all resources' })
  deleteAccount(
    @Request() req: any,
    @Res({ passthrough: true }) res: Response,
  ) {
    res.clearCookie('access_token');
    return this.authService.deleteAccount(req.user.id);
  }

  @Get('users')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN')
  @ApiOperation({ summary: 'Admin: Get all users' })
  @ApiResponse({
    status: 200,
    description: 'Returns an array of all users and their project counts.',
  })
  getAllUsers() {
    return this.authService.getAllUsers();
  }

  @Get('users/:id')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN')
  @ApiOperation({ summary: 'Admin: Get user by ID' })
  @ApiParam({ name: 'id', description: 'The ID of the user' })
  @ApiResponse({
    status: 200,
    description:
      'Returns detailed information of a specific user including their projects.',
  })
  @ApiResponse({ status: 400, description: 'User not found.' })
  getUserById(@Param('id') id: string) {
    return this.authService.getUserById(id);
  }

  @Delete('users/:id')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN')
  @ApiOperation({ summary: 'Admin: Delete user by ID and all resources' })
  @ApiParam({
    name: 'id',
    description: 'The ID of the user to permanently delete',
  })
  @ApiResponse({
    status: 200,
    description:
      'User and all associated containers/projects successfully deleted.',
  })
  deleteUserById(@Param('id') id: string) {
    return this.authService.deleteAccount(id);
  }

  @Delete('users')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN')
  @ApiOperation({ summary: 'Admin: Delete all users and all resources (Nuke)' })
  @ApiResponse({
    status: 200,
    description:
      'All users and their containers successfully wiped from the server.',
  })
  deleteAllUsers() {
    return this.authService.deleteAllUsers();
  }
}

import { Module } from '@nestjs/common';
import { JwtModule } from '@nestjs/jwt';
import { PassportModule } from '@nestjs/passport';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { AuthService } from './auth.service';
import { AuthController } from './auth.controller';
import { JwtStrategy } from './strategies/jwt.strategy';
import { ProjectsModule } from '../projects/projects.module';

@Module({
  imports: [
    PassportModule,
    JwtModule.registerAsync({
      imports: [ConfigModule],
      inject: [ConfigService],
      useFactory: (config: ConfigService) => ({
        secret: config.get<string>('JWT_SECRET') as string,
        signOptions: {
          expiresIn: config.get<string>('JWT_EXPIRES_IN', '7d') as any,
        },
      }),
    }),
    ProjectsModule,
  ],
  providers: [AuthService, JwtStrategy],
  controllers: [AuthController],
  exports: [AuthService, JwtModule],
})
export class AuthModule {}

import {
  Injectable,
  ConflictException,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma/prisma.service';
import { ProjectsService } from '../projects/projects.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';
import { UpdateProfileDto } from './dto/update-profile.dto';
import { UpdatePasswordDto } from './dto/update-password.dto';
import * as crypto from 'crypto';
import { promisify } from 'util';
import { exec } from 'child_process';
import * as fs from 'fs/promises';

const generateKeyPair = promisify(crypto.generateKeyPair);
const execAsync = promisify(exec);

@Injectable()
export class AuthService {
  constructor(
    private prisma: PrismaService,
    private jwtService: JwtService,
    private projectsService: ProjectsService,
  ) {}

  async register(dto: RegisterDto, ip: string) {
    await this.verifyTurnstileToken(dto.turnstileToken);

    const existing = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (existing) {
      throw new ConflictException('Email already registered');
    }

    const hashedPassword = await bcrypt.hash(dto.password, 12);

    const user = await this.prisma.user.create({
      data: {
        name: dto.name,
        email: dto.email,
        password: hashedPassword,
      },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
      },
    });

    await this.prisma.activityLog.create({
      data: {
        userId: user.id,
        action: 'REGISTER',
        description: 'User registered',
        ipAddress: ip,
      },
    });

    const token = this.generateToken(user);
    return { user, token };
  }

  async login(dto: LoginDto, ip: string) {
    await this.verifyTurnstileToken(dto.turnstileToken);

    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });

    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const passwordMatch = await bcrypt.compare(dto.password, user.password);
    if (!passwordMatch) {
      throw new UnauthorizedException('Invalid credentials');
    }

    await this.prisma.activityLog.create({
      data: {
        userId: user.id,
        action: 'LOGIN',
        description: 'User logged in',
        ipAddress: ip,
      },
    });

    const { password: _, ...userWithoutPassword } = user;
    const token = this.generateToken(user);
    return { user: userWithoutPassword, token };
  }

  async getMe(userId: string) {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        email: true,
        createdAt: true,
        updatedAt: true,
      },
    });
    return user;
  }

  async updateProfile(userId: string, dto: UpdateProfileDto, ip: string) {
    const existingEmail = await this.prisma.user.findFirst({
      where: { email: dto.email, id: { not: userId } },
    });

    if (existingEmail) {
      throw new ConflictException('Email is already in use by another account');
    }

    const user = await this.prisma.user.update({
      where: { id: userId },
      data: {
        name: dto.name,
        email: dto.email,
      },
      select: {
        id: true,
        name: true,
        email: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    await this.prisma.activityLog.create({
      data: {
        userId,
        action: 'UPDATE_PROFILE',
        description: 'User updated profile information',
        ipAddress: ip,
      },
    });

    return user;
  }

  async updatePassword(userId: string, dto: UpdatePasswordDto, ip: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new UnauthorizedException('User not found');

    const passwordMatch = await bcrypt.compare(
      dto.currentPassword,
      user.password,
    );
    if (!passwordMatch) {
      throw new BadRequestException('Current password is incorrect');
    }

    const hashedPassword = await bcrypt.hash(dto.newPassword, 12);

    await this.prisma.user.update({
      where: { id: userId },
      data: { password: hashedPassword },
    });

    await this.prisma.activityLog.create({
      data: {
        userId,
        action: 'UPDATE_PASSWORD',
        description: 'User changed password',
        ipAddress: ip,
      },
    });

    return { message: 'Password updated successfully' };
  }

  async generateSshKey(userId: string, ip: string) {
    const keyPath = `/tmp/key_${userId}_${Date.now()}`;
    try {
      await execAsync(
        `ssh-keygen -t ed25519 -C "portdock_${userId}" -N "" -f ${keyPath}`,
      );
      const privateKey = await fs.readFile(keyPath, 'utf8');
      const publicKey = await fs.readFile(`${keyPath}.pub`, 'utf8');

      const user = await this.prisma.user.update({
        where: { id: userId },
        data: {
          sshPrivateKey: privateKey,
          sshPublicKey: publicKey.trim(),
        },
      });

      await fs.unlink(keyPath).catch(() => {});
      await fs.unlink(`${keyPath}.pub`).catch(() => {});

      await this.prisma.activityLog.create({
        data: {
          userId,
          action: 'GENERATE_SSH_KEY',
          description: 'User generated a new SSH key',
          ipAddress: ip,
        },
      });

      return { sshPublicKey: user.sshPublicKey };
    } catch (error) {
      throw new BadRequestException('Failed to generate SSH key');
    }
  }

  async connectGithub(userId: string, token: string, ip: string) {
    try {
      const res = await fetch('https://api.github.com/user', {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Invalid token');
      const data = await res.json();

      const user = await this.prisma.user.update({
        where: { id: userId },
        data: {
          githubToken: token,
          githubUsername: data.login,
        },
      });

      await this.prisma.activityLog.create({
        data: {
          userId,
          action: 'CONNECT_GITHUB',
          description: `User connected GitHub account: ${data.login}`,
          ipAddress: ip,
        },
      });

      return { githubUsername: user.githubUsername };
    } catch (err) {
      throw new BadRequestException(
        'Failed to connect GitHub: Invalid Personal Access Token',
      );
    }
  }

  async disconnectGithub(userId: string, ip: string) {
    await this.prisma.user.update({
      where: { id: userId },
      data: {
        githubToken: null,
        githubUsername: null,
      },
    });

    await this.prisma.activityLog.create({
      data: {
        userId,
        action: 'DISCONNECT_GITHUB',
        description: 'User disconnected GitHub account',
        ipAddress: ip,
      },
    });

    return { message: 'GitHub account disconnected' };
  }

  private generateToken(user: {
    id: string;
    email: string;
    name: string;
    role?: string;
  }) {
    return this.jwtService.sign({
      sub: user.id,
      email: user.email,
      name: user.name,
      role: user.role || 'USER',
    });
  }

  private async verifyTurnstileToken(token: string | undefined) {
    if (process.env.NODE_ENV !== 'development' && !token) {
      throw new UnauthorizedException('Turnstile verification required');
    }

    const secretKey = process.env.TURNSTILE_SECRET_KEY;
    if (!secretKey || !token) return;

    try {
      const response = await fetch(
        'https://challenges.cloudflare.com/turnstile/v0/siteverify',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            secret: secretKey,
            response: token,
          }),
        },
      );

      const data = await response.json();
      if (!data.success) {
        throw new UnauthorizedException('Turnstile verification failed');
      }
    } catch (error) {
      if (error instanceof UnauthorizedException) throw error;
      throw new UnauthorizedException('Failed to verify Turnstile token');
    }
  }

  async getAllUsers() {
    return this.prisma.user.findMany({
      select: {
        id: true,
        name: true,
        email: true,
        createdAt: true,
        updatedAt: true,
        _count: {
          select: { projects: true },
        },
      },
      orderBy: { createdAt: 'desc' },
    });
  }

  async getUserById(userId: string) {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        email: true,
        createdAt: true,
        updatedAt: true,
        projects: {
          select: {
            id: true,
            name: true,
            domain: true,
            status: true,
          },
        },
      },
    });

    if (!user) throw new BadRequestException('User not found');
    return user;
  }

  async deleteAccount(userId: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new BadRequestException('User not found');

    const projects = await this.prisma.project.findMany({ where: { userId } });
    for (const project of projects) {
      await this.projectsService.remove(project.id, userId);
    }

    await this.prisma.user.delete({ where: { id: userId } });
    return {
      message: 'User account and all associated resources deleted successfully',
    };
  }

  async deleteAllUsers() {
    const users = await this.prisma.user.findMany({
      where: { role: 'USER' },
    });
    let deletedCount = 0;

    for (const user of users) {
      try {
        await this.deleteAccount(user.id);
        deletedCount++;
      } catch (error) {
        console.error(`Failed to delete user ${user.id}:`, error);
      }
    }

    return {
      message: `Successfully deleted ${deletedCount} users and their resources`,
    };
  }
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';
import { Role } from '@generated/prisma';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (!requiredRoles) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();
    return requiredRoles.some((role) => user?.role === role);
  }
}

import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { ConfigService } from '@nestjs/config';
import { Request } from 'express';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(configService: ConfigService) {
    super({
      jwtFromRequest: (req: Request) => {
        let token = null;
        if (req && req.cookies) {
          token = req.cookies['access_token'];
        }
        return token || ExtractJwt.fromAuthHeaderAsBearerToken()(req);
      },
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('JWT_SECRET') as string,
    });
  }

  async validate(payload: {
    sub: string;
    email: string;
    name: string;
    role: string;
  }) {
    return {
      id: payload.sub,
      email: payload.email,
      name: payload.name,
      role: payload.role,
    };
  }
}

import {
  Injectable,
  Logger,
  InternalServerErrorException,
} from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { ConfigService } from '@nestjs/config';
import * as fs from 'fs';
import * as path from 'path';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

@Injectable()
export class BackupService {
  private readonly logger = new Logger(BackupService.name);
  private readonly backupDir: string;
  private readonly RETENTION_DAYS = 7;

  constructor(private configService: ConfigService) {
    this.backupDir = path.resolve(process.cwd(), 'backups');
    if (!fs.existsSync(this.backupDir)) {
      fs.mkdirSync(this.backupDir, { recursive: true });
    }
  }

  // Runs every day at 02:00 AM
  @Cron('0 2 * * *')
  async handleDailyBackup() {
    this.logger.log('Starting scheduled daily backup...');
    try {
      await this.runBackup();
    } catch (error) {
      this.logger.error(`Scheduled backup failed: ${error.message}`);
    }
  }

  async runBackup() {
    try {
      const dbUrl = this.configService.get<string>('DATABASE_URL');
      if (!dbUrl) {
        throw new Error('DATABASE_URL is not defined in environment variables');
      }

      // Parse the DB URL to extract credentials
      const parsedUrl = new URL(dbUrl);
      const username = parsedUrl.username;
      const password = parsedUrl.password;
      const host = parsedUrl.hostname;
      const port = parsedUrl.port || '5432';
      const dbName = parsedUrl.pathname.substring(1);

      // Generate filename with current date and time
      const date = new Date();
      const timestamp = date.toISOString().replace(/[:.]/g, '-');
      const filename = `backup_${timestamp}.sql.gz`;
      const filePath = path.join(this.backupDir, filename);

      this.logger.log(`Generating backup: ${filename}...`);

      // Construct Docker command to run pg_dump and pipe to gzip
      // Using postgres:15 alpine image because it's small and contains pg_dump
      const dockerCmd = `docker run --rm --network host -e PGPASSWORD="${password}" postgres:15-alpine pg_dump -h ${host} -p ${port} -U ${username} -d ${dbName} | gzip > ${filePath}`;

      const { stdout, stderr } = await execAsync(dockerCmd);

      if (stderr) {
        // Warning: pg_dump sometimes writes non-errors to stderr, but we log it just in case
        this.logger.debug(`pg_dump stderr: ${stderr}`);
      }

      this.logger.log(`Backup completed successfully: ${filePath}`);

      // Run cleanup policy
      await this.enforceRetentionPolicy();

      return {
        message: 'Backup completed successfully',
        filename,
        path: filePath,
      };
    } catch (error) {
      this.logger.error('Database backup failed', error);
      throw new InternalServerErrorException(`Backup failed: ${error.message}`);
    }
  }

  private async enforceRetentionPolicy() {
    try {
      const files = fs
        .readdirSync(this.backupDir)
        .filter((file) => file.endsWith('.sql.gz'))
        .map((file) => ({
          name: file,
          path: path.join(this.backupDir, file),
          time: fs.statSync(path.join(this.backupDir, file)).mtime.getTime(),
        }))
        .sort((a, b) => b.time - a.time); // Descending (newest first)

      if (files.length > this.RETENTION_DAYS) {
        this.logger.log(
          `Retention policy: Found ${files.length} backups. Deleting backups older than ${this.RETENTION_DAYS} files...`,
        );

        // Delete all files beyond the RETENTION_DAYS threshold
        const filesToDelete = files.slice(this.RETENTION_DAYS);
        for (const file of filesToDelete) {
          fs.unlinkSync(file.path);
          this.logger.log(`Deleted old backup: ${file.name}`);
        }
      }
    } catch (error) {
      this.logger.error('Failed to enforce retention policy', error);
    }
  }
}

